  const tags = ["[GW_TAG_01_BLOG_IDENTITY]","[GW_TAG_02_SEO_METADATA]","[GW_TAG_03_HERO_HOOK]","[GW_TAG_04_CONTEXT_SETUP]","[GW_TAG_05_PROBLEM_BREAKDOWN]","[GW_TAG_06_SOLUTION_OVERVIEW]","[GW_TAG_07_IMPLEMENTATION_STEPS]","[GW_TAG_08_CODE_SNIPPETS]","[GW_TAG_09_CODE_EXPLANATION]","[GW_TAG_10_VALIDATION_CHECKLIST]","[GW_TAG_11_EDGE_CASES]","[GW_TAG_12_BEST_PRACTICES]","[GW_TAG_13_PRO_TIPS]","[GW_TAG_14_RESOURCES]","[GW_TAG_15_FINAL_THOUGHTS]","[GW_TAG_16_PREVIEW_CARD_DATA]","[GW_TAG_17_IMAGE_PLAN]","[GW_TAG_18_KEY_CONCEPTS]"];
  let last = -1;
  for (const tag of tags) {
    const idx = text.indexOf(tag.toLowerCase());
    if (idx === -1 || idx < last) return false;
    last = idx;
  }

  const sec = (a, b) => {
    const s = text.indexOf(a.toLowerCase());
    if (s === -1) return "";
    const from = s + a.length;
    const e = b ? text.indexOf(b.toLowerCase(), from) : -1;
    return (e === -1 ? text.slice(from) : text.slice(from, e)).trim();
  };

  const bodySec = sec("[GW_TAG_03_HERO_HOOK]", "[GW_TAG_15_FINAL_THOUGHTS]");
  const stepsSec = sec("[GW_TAG_07_IMPLEMENTATION_STEPS]", "[GW_TAG_08_CODE_SNIPPETS]");
