  const stop = new Set(["how","to","use","using","with","in","for","and","the","a","an","on","of","from","guide","tutorial","overview","basics"]);
  const topicTerms = [...new Set((topic.match(/[a-z0-9.+#-]+/g) || []).filter(w => w.length >= 3 && !stop.has(w)))].slice(0, 12);
  const researchTerms = [...new Set((research.match(/[a-z0-9.+#-]+/g) || []).filter(w => w.length >= 4 && !stop.has(w)))].slice(0, 20);
  const keys = [...new Set([...topicTerms, ...researchTerms])].slice(0, 14);

  if (!keys.length) return false;

  const hits = (s) => keys.filter(k => s.includes(k)).length;

  const bodyHits = hits(bodySec);
  const stepHits = hits(stepsSec);
  const codeHits = hits(codeSec);
  const totalHits = hits(text);

  if (totalHits < Math.min(4, keys.length)) return false;
  if (bodyHits < Math.min(2, keys.length)) return false;
  if (stepHits < 1) return false;
  if (codeHits < 1) return false;

  return true;
})() }}

