parameters.jsCode:
const text = ($json.final_blog_output || "").trim();
const tagNames = [
  "GW_TAG_01_BLOG_IDENTITY","GW_TAG_02_SEO_METADATA","GW_TAG_03_HERO_HOOK","GW_TAG_04_CONTEXT_SETUP",
  "GW_TAG_05_PROBLEM_BREAKDOWN","GW_TAG_06_SOLUTION_OVERVIEW","GW_TAG_07_IMPLEMENTATION_STEPS","GW_TAG_08_CODE_SNIPPETS",
  "GW_TAG_09_CODE_EXPLANATION","GW_TAG_10_VALIDATION_CHECKLIST","GW_TAG_11_EDGE_CASES","GW_TAG_12_BEST_PRACTICES",
  "GW_TAG_13_PRO_TIPS","GW_TAG_14_RESOURCES","GW_TAG_15_FINAL_THOUGHTS","GW_TAG_16_PREVIEW_CARD_DATA","GW_TAG_17_IMAGE_PLAN","GW_TAG_18_KEY_CONCEPTS"
];

const sections = {};
for (let i = 0; i < tagNames.length; i++) {
  const open = `[${tagNames[i]}]`;
  const start = text.indexOf(open);
  if (start === -1) continue;
  const contentStart = start + open.length;
  let end = text.length;
  for (let j = i + 1; j < tagNames.length; j++) {
    const next = text.indexOf(`[${tagNames[j]}]`, contentStart);
    if (next !== -1) { end = next; break; }
  }
  sections[tagNames[i]] = text.slice(contentStart, end).trim();
}

return [{ json: { ...$json, sections, parsed_tag_count: Object.keys(sections).length } }];

const s = $json.sections || {};
const get = (k) => (s[k] || "").trim();

const parseKV = (block) => {
  const out = {};
  (block || "").split("\n").forEach((line) => {
    const m = line.match(/^\s*[-*]?\s*([A-Za-z0-9 _-]+?)\s*:\s*(.+)\s*$/);
    if (m) out[m[1].trim().toLowerCase()] = m[2].trim();
  });
  return out;
};

const bullets = (block) =>
  (block || "")
    .split("\n")
    .map((x) => x.trim())
    .filter((x) => /^-\s+/.test(x))
    .map((x) => x.replace(/^-\s+/, "").trim());

const paragraphs = (block) =>
  (block || "")
    .split(/\n\n+/)
    .map((x) => x.trim())
    .filter(Boolean);

const trimWords = (text, maxWords = 45) => {
  const t = String(text || "").replace(/\s+/g, " ").trim();
  if (!t) return "";
  const parts = t.split(" ");
  return parts.length <= maxWords ? t : `${parts.slice(0, maxWords).join(" ")}...`;
};

const compactParagraphs = (arr, maxParas = 2, maxWords = 45) =>
  (arr || []).map((x) => trimWords(x, maxWords)).filter(Boolean).slice(0, maxParas);

const compactBullets = (arr, maxItems = 8, maxWords = 22) =>
  (arr || []).map((x) => trimWords(x, maxWords)).filter(Boolean).slice(0, maxItems);

const topic = String($json.topic || "").trim();
const topicLower = topic.toLowerCase();
const stop = new Set(["how","to","use","using","with","in","for","and","the","a","an","on","of","from","guide","tutorial","overview","basics"]);
const topicTerms = [...new Set((topicLower.match(/[a-z0-9.+#-]+/g) || []).filter((w) => w.length >= 3 && !stop.has(w)))].slice(0, 12);

const researchContext = String($json.research_context || "");
const rcLower = researchContext.toLowerCase();
const researchTerms = [...new Set((rcLower.match(/[a-z0-9.+#-]+/g) || []).filter((w) => w.length >= 4 && !stop.has(w)))].slice(0, 20);
const keyTerms = [...new Set([...topicTerms, ...researchTerms])].slice(0, 12);

const inferLang = () => {
  if (/\b(flutter|dart|android|ios|widget)\b/.test(topicLower)) return "dart";
  if (/\b(next|react|typescript|tsx|javascript|node|frontend|web)\b/.test(topicLower)) return "tsx";
  if (/\b(python|fastapi|django|flask)\b/.test(topicLower)) return "python";
  if (/\b(java|spring)\b/.test(topicLower)) return "java";
  if (/\b(go|golang)\b/.test(topicLower)) return "go";
  return "text";
};
const isCodeRelevant = (block) => {
  const txt = String((block && block.code) || "").toLowerCase();
  if (!txt.trim()) return false;

  const installTopic = /\b(install|setup|configure|windows|macos|linux|sdk|path|environment|doctor)\b/.test(topicLower);
  const commandSignals = /\b(flutter\s+doctor|flutter\s+--version|flutter\s+config|setx\s+|set\s+path|export\s+path|path\s*=|choco\s+install|winget\s+install|sdkmanager\s+|adb\s+--version|android\s+studio|visual\s+studio|git\s+--version)\b/.test(txt);

  // reject generic/fake program code for installation topics
  const genericCodeSignals = /\b(class\s+\w+|bool\s+validate\s*\(|def\s+validate\s*\(|function\s+validate\s*\(|featureservice|invoke-expression|write-host\s+"===|foreach\s*\(|while\s*\(|try\s*\{|catch\s*\{)\b/.test(txt);

  if (installTopic) {
    if (genericCodeSignals) return false;
    return commandSignals;
  }

  if (!keyTerms.length) return true;
  const hits = keyTerms.filter((k) => txt.includes(k)).length;
  return hits >= Math.min(2, keyTerms.length);
};

const identity = parseKV(get("GW_TAG_01_BLOG_IDENTITY"));
const seo = parseKV(get("GW_TAG_02_SEO_METADATA"));

let title = identity.title || topic || "Generated Blog";
let slug = identity.slug || title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
if (!slug) slug = "generated-blog";

const readTimeRaw = seo.suggestedreadtime || seo.readtime || "8";
const readTime = (String(readTimeRaw).match(/\d+/) || ["8"])[0];

let hero = compactParagraphs(paragraphs(get("GW_TAG_03_HERO_HOOK")), 2, 42);
let context = compactParagraphs(paragraphs(get("GW_TAG_04_CONTEXT_SETUP")), 2, 40);
let problem = compactBullets(bullets(get("GW_TAG_05_PROBLEM_BREAKDOWN")), 8, 20);
let solution = compactParagraphs(paragraphs(get("GW_TAG_06_SOLUTION_OVERVIEW")), 2, 40);
let best = compactBullets(bullets(get("GW_TAG_12_BEST_PRACTICES")), 8, 18);
let tips = compactBullets(bullets(get("GW_TAG_13_PRO_TIPS")), 8, 18);
let finalThoughts = compactParagraphs(paragraphs(get("GW_TAG_15_FINAL_THOUGHTS")), 2, 40);

let steps = (get("GW_TAG_07_IMPLEMENTATION_STEPS") || "")
  .split("\n")
  .map((x) => x.trim())
  .filter((x) => /^(\*\*\s*)?step\s+\d+/i.test(x) || /^-\s+/.test(x))
  .map((x) => trimWords(x.replace(/^[-*\s]+/, "").trim(), 20));

const codeRegex = /```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```/g;
const codeRaw = get("GW_TAG_08_CODE_SNIPPETS");
let codeBlocks = [];
let m;
while ((m = codeRegex.exec(codeRaw)) !== null) {
  const b = { language: (m[1] || "text").trim() || "text", code: (m[2] || "").trim() };
  if (isCodeRelevant(b)) codeBlocks.push(b);
}

const matchCount = (txt) => keyTerms.filter((k) => txt.includes(k)).length;
const blob = [title, ...hero, ...context, ...problem, ...solution, ...steps, ...best, ...tips, ...finalThoughts, ...codeBlocks.map((b) => `${b.language}\n${b.code}`)].join("\n").toLowerCase();
const coherenceScore = matchCount(blob);
const lowCoherence = keyTerms.length > 0 && coherenceScore < Math.min(3, keyTerms.length);

if (lowCoherence || !hero.length || !context.length || !problem.length || !solution.length || !best.length || !tips.length || !finalThoughts.length || steps.length < 5) {
  const topicLabel = topic || "the topic";
  const pointLines = (researchContext || "").split("\n").map((x) => x.trim()).filter((x) => /^[-*]\s+/.test(x)).map((x) => x.replace(/^[-*]\s+/, ""));

  hero = [
    trimWords(`${topicLabel} matters in real projects because weak implementation choices create hard-to-debug failures and inconsistent user experience.`, 32),
    trimWords(`This guide uses focused, production-oriented steps and code examples grounded in official references.`, 22)
  ];

  context = [
    trimWords(`We start with minimal setup, then move to implementation patterns and validation checkpoints for ${topicLabel}.`, 30)
  ];

  problem = (pointLines.slice(0, 5).length ? pointLines.slice(0, 5) : [
    `Unclear setup path for ${topicLabel}`,
    `Inconsistent implementation patterns`,
    `Missing validation for edge cases`
  ]).map((x) => trimWords(x, 18));

  solution = [trimWords(`Apply a step-by-step architecture: setup, core implementation, validation, and performance checks for ${topicLabel}.`, 28)];

  steps = [
    `Step 1: Define prerequisites and expected behavior for ${topicLabel}.`,
    `Step 2: Implement a minimal working baseline.`,
    `Step 3: Add robust handling for non-happy paths.`,
    `Step 4: Improve structure for reuse and readability.`,
    `Step 5: Validate with realistic usage scenarios.`
  ].map((x) => trimWords(x, 20));

  const lang = inferLang();
  // Do not inject synthetic generic code snippets.
  // Keep only model-generated/topic-relevant code. If none, render text-only steps.
  codeBlocks = (codeBlocks || []).filter(isCodeRelevant);

  best = [
    "Keep implementation modular and testable",
    "Use one clear source of truth for configuration",
    "Validate behavior before optimization"
  ];
  tips = [
    "Prefer concise code snippets with clear intent",
    "Document edge cases and trade-offs",
    "Use official docs for API-level decisions"
  ];
  finalThoughts = [trimWords(`Treat ${topicLabel} as an iterative build: baseline first, then reliability and performance hardening.`, 24)];
}

const officialDomains = (Array.isArray($json.official_sources) ? $json.official_sources : [])
  .map((r) => {
    try { return new URL(String(r.url || "")).hostname.replace(/^www\./, "").toLowerCase(); } catch { return ""; }
  })
  .filter(Boolean);

// widely accepted general reference domains (topic-agnostic)
const acceptedDomains = [
  "stackoverflow.com","github.com","gitlab.com","wikipedia.org"
];

const isTrustedResource = (url) => {
  try {
    const host = new URL(String(url || "")).hostname.replace(/^www\./, "").toLowerCase();
    if (officialDomains.some((d) => host === d || host.endsWith(`.${d}`))) return true;
    return acceptedDomains.some((d) => host === d || host.endsWith(`.${d}`));
  } catch {
    return false;
  }
};

const resRaw = get("GW_TAG_14_RESOURCES");
const resources = [];
const mdLink = /\[([^\]]+)\]\(([^)]+)\)/g;
let l;
while ((l = mdLink.exec(resRaw)) !== null) {
  const href = l[2].trim();
  if (isTrustedResource(href)) resources.push({ label: l[1].trim(), href: href });
}

if (!resources.length && Array.isArray($json.official_sources) && $json.official_sources.length) {
  $json.official_sources.forEach((r) => {
    if (r && r.label && r.url) resources.push({ label: String(r.label), href: String(r.url) });
  });
}

const kcRaw = get("GW_TAG_18_KEY_CONCEPTS");
let conceptsTitle = "Key Concepts Covered";
let conceptItems = [];
let highlightTokens = [];
if (kcRaw) {
  const lines = kcRaw.split("\n").map((x) => x.trim()).filter(Boolean);
  let mode = "items";
  for (const line of lines) {
    const st = line.match(/^[-*]?\s*sectionTitle\s*:\s*(.+)$/i);
    if (st) { conceptsTitle = st[1].trim(); continue; }
    if (/^[-*]?\s*items\s*:/i.test(line)) { mode = "items"; continue; }
    if (/^[-*]?\s*highlightTokens\s*:/i.test(line)) { mode = "tokens"; continue; }
    if (/^-\s+/.test(line)) {
      const v = line.replace(/^-\s+/, "").trim();
      if (mode === "tokens") highlightTokens.push(v.replace(/^`|`$/g, ""));
      else conceptItems.push(v);
    }
  }
}
if (!conceptItems.length) {
  conceptItems = [
    `Core setup for ${topic || "the topic"}`,
    "Implementation flow and reusable patterns",
    "Validation and optimization strategy"
  ];
}
if (!highlightTokens.length) {
  highlightTokens = keyTerms.length ? keyTerms.slice(0, 8) : ["Setup", "Implementation", "Validation"];
}

const componentName = "GeneratedBlogPage";

return [{
  json: {
    ...$json,
    title,
    slug,
    readTime,
    componentName,
    hero,
    context,
    problem,
    solution,
    steps,
    best,
    tips,
    finalThoughts,
    codeBlocks,
    resources,
    conceptsTitle,
    conceptItems,
    highlightTokens,
  }
}];

const d = $json;

const q = (v) => JSON.stringify(String(v ?? ""));
const esc = (s) => String(s || "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/\{/g, "&#123;")
  .replace(/\}/g, "&#125;");

const stripInlineMd = (v) => String(v || "")
  .replace(/\*\*(.*?)\*\*/g, "$1")
  .replace(/`([^`]+)`/g, "$1")
  .replace(/~~(.*?)~~/g, "$1")
  .replace(/\[(.*?)\]\((https?:\/\/[^\s)]+)\)/g, "$1 ($2)")
  .replace(/\s+/g, " ")
  .trim();

const cleanArr = (arr) => (arr || []).map((x) => stripInlineMd(x)).filter(Boolean);
const para = (arr) => cleanArr(arr).map((p) => `\n        <BlogContent>{${q(p)}}</BlogContent>`).join("");
const listItems = (arr, fallback) => {
  const cleaned = cleanArr(arr);
  return cleaned.length ? cleaned.map((x) => q(x)).join(",\n              ") : q(fallback);
};

const ext = (lang) => {
  const m = { typescript: "ts", javascript: "js", tsx: "tsx", jsx: "jsx", bash: "sh", shell: "sh", dart: "dart", rust: "rs", python: "py", json: "json", yaml: "yml", toml: "toml", markdown: "md" };
  const key = String(lang || "txt").toLowerCase();
  return m[key] || key.replace(/[^a-z0-9]/g, "") || "txt";
};

const conceptChips = (d.highlightTokens || []).length
  ? cleanArr(d.highlightTokens).map((t, i) => `<span key={${q(String(i))}} className=\"inline-flex\"><BlogHighlighter>${esc(t)}</BlogHighlighter></span>`).join("\n            ")
  : `<span key=\"0\" className=\"inline-flex\"><BlogHighlighter>Topic</BlogHighlighter></span>`;

const conceptItemsJsx = (d.conceptItems || []).length
  ? cleanArr(d.conceptItems).map((line, i) => `<React.Fragment key={${q(`ci-${i}`)}}>${esc(line)}</React.Fragment>`).join(",\n              ")
  : `<React.Fragment key=\"ci-0\">Core concepts from generated content</React.Fragment>`;

const resourceItems = (d.resources || []).length
  ? d.resources.map((r, i) => `<Link key={${q(String(i))}} href={${q(r.href)}} target=\"_blank\" rel=\"noopener noreferrer\" className=\"text-sky-400 hover:text-sky-600\">${esc(stripInlineMd(r.label))}</Link>`).join(",\n            ")
  : `<Link key=\"0\" href=\"https://docs.flutter.dev/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"text-sky-400 hover:text-sky-600\">Official Docs</Link>`;

const stepItems = (d.steps || []).length ? cleanArr(d.steps) : ["Step 1: Implement solution"];
const codeBlocks = d.codeBlocks || [];
const pairedCount = Math.min(stepItems.length, codeBlocks.length);

const interleavedStepCode = Array.from({ length: pairedCount }).map((_, i) => {
  const step = String(stepItems[i] || "").replace(/^[-*\s]+/, "").trim();
  const block = codeBlocks[i] || { language: "text", code: "" };
  return `\n        <BlogSubTitle>{${q(step)}}</BlogSubTitle>\n        <CodeBlock\n          language={${q(block.language || "text")}}\n          filename={${q(`snippet-${i + 1}.${ext(block.language)}`)}}\n          code={${q(block.code || "")}}\n        />`;
}).join("\n");

const remainingStepItems = stepItems.slice(pairedCount);
const remainingStepsBlock = remainingStepItems.length
  ? `\n        <BlogSubTitle>Additional Implementation Notes</BlogSubTitle>\n        <BlogList items={[\n              ${remainingStepItems.map((x) => q(x)).join(",\n              ")}\n        ]} />`
  : "";

const rawTagOrder = [
  "GW_TAG_01_BLOG_IDENTITY","GW_TAG_02_SEO_METADATA","GW_TAG_03_HERO_HOOK","GW_TAG_04_CONTEXT_SETUP",
  "GW_TAG_05_PROBLEM_BREAKDOWN","GW_TAG_06_SOLUTION_OVERVIEW","GW_TAG_07_IMPLEMENTATION_STEPS","GW_TAG_08_CODE_SNIPPETS",
  "GW_TAG_09_CODE_EXPLANATION","GW_TAG_10_VALIDATION_CHECKLIST","GW_TAG_11_EDGE_CASES","GW_TAG_12_BEST_PRACTICES",
  "GW_TAG_13_PRO_TIPS","GW_TAG_14_RESOURCES","GW_TAG_15_FINAL_THOUGHTS","GW_TAG_16_PREVIEW_CARD_DATA",
  "GW_TAG_17_IMAGE_PLAN","GW_TAG_18_KEY_CONCEPTS"
];

