const renderNonCodeText = (text) => {
  const lines = String(text || "").split("\n");
  const out = [];
  let bullets = [];

  const parseTableRow = (line) => line
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map((c) => stripInlineMd(c.trim()));

  const isTableLine = (line) => /^\|.*\|$/.test(line);
  const isTableSeparator = (line) => /^(\|\s*:?-{3,}:?\s*)+\|?$/.test(line);

  const flushBullets = () => {
    if (!bullets.length) return;
    out.push(`\n        <BlogList items={[\n              ${bullets.map((b) => q(stripInlineMd(b))).join(",\n              ")}\n        ]} />`);
    bullets = [];
  };

  let i = 0;
  while (i < lines.length) {
    let line = (lines[i] || "").trim();

    if (!line) {
      flushBullets();
      i += 1;
      continue;
    }

    if (/^\[GW_TAG_\d+_[A-Z_]+\]$/i.test(line)) {
      i += 1;
      continue;
    }

    if (/^[-*]\s+/.test(line)) {
      bullets.push(line.replace(/^[-*]\s+/, "").trim());
      i += 1;
      continue;
    }

    flushBullets();

    if (/^#{1,6}\s+/.test(line)) {
      out.push(`\n        <BlogSubTitle>{${q(stripInlineMd(line.replace(/^#{1,6}\s+/, "").trim()))}}</BlogSubTitle>`);
      i += 1;
      continue;
    }

    const next = (lines[i + 1] || "").trim();
    if (isTableLine(line) && isTableSeparator(next)) {
      const headers = parseTableRow(line);
      const rows = [];
      i += 2;
      while (i < lines.length && isTableLine((lines[i] || "").trim())) {
        rows.push(parseTableRow((lines[i] || "").trim()));
        i += 1;
      }

      if (headers.length) {
        const head = headers.map((h) => `<th className=\"border border-white/15 px-3 py-2 text-left\">${esc(h)}</th>`).join("");
        const body = rows.map((r) => {
          const tds = headers.map((_, ci) => `<td className=\"border border-white/10 px-3 py-2 align-top\">${esc(r[ci] || "")}</td>`).join("");
          return `<tr>${tds}</tr>`;
        }).join("");

        out.push(`\n        <div className=\"overflow-x-auto\">\n          <table className=\"w-full text-sm border border-white/15 rounded-md overflow-hidden\">\n            <thead className=\"bg-white/5\">\n              <tr>${head}</tr>\n            </thead>\n            <tbody>${body}</tbody>\n          </table>\n        </div>`);
      }
      continue;
    }

    out.push(`\n        <BlogContent>{${q(stripInlineMd(line))}}</BlogContent>`);
    i += 1;
  }

  flushBullets();
  return out.join("");
};
const renderRawSection = (tag, raw) => {
  const parts = [];
  const src = String(raw || "");
  const re = /```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```/g;
  let last = 0;
  let m;
  let codeIndex = 1;

  while ((m = re.exec(src)) !== null) {
    const before = src.slice(last, m.index);
    if (before.trim()) parts.push(renderNonCodeText(before));

    const lang = (m[1] || "text").trim() || "text";
    const code = (m[2] || "").trim();
    parts.push(`\n        <CodeBlock\n          language={${q(lang)}}\n          filename={${q(`${(sectionFileBaseMap[tag] || "snippet")}-${codeIndex}.${ext(lang)}`)}}\n          code={${q(code)}}\n        />`);
    codeIndex += 1;
    last = m.index + m[0].length;
  }

  const tail = src.slice(last);
  if (tail.trim()) parts.push(renderNonCodeText(tail));

  if (!parts.length) return "";
  const niceTitle = tagTitleMap[tag] || "Generated Section";
  return `\n        <BlogSubTitle>{${q(niceTitle)}}</BlogSubTitle>${parts.join("")}`;
};

