  "[IO.File]::WriteAllBytes($componentPath, [Convert]::FromBase64String($componentB64))",
  `$pageB64 = '${pageB64}'`,
  "$pagePath = Join-Path $blogDir 'page.tsx'",
  "[IO.File]::WriteAllBytes($pagePath, [Convert]::FromBase64String($pageB64))",
